   119  int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
   120      hFILE *memfile;
   121      uint8_t *copy = malloc(size);
   122      if (copy == NULL) {
   123          abort();
   124      }
   125      memcpy(copy, data, size);
   126      // hopen does not take ownership of `copy`, but hts_hopen does.
   127      memfile = hopen("mem:", "rb:", copy, size);
   128      if (memfile == NULL) {
   129          free(copy);
   130          return 0;
   131      }
   132
   133      htsFile *ht_file = hts_hopen(memfile, "data", "rb");
   134      if (ht_file == NULL) {
   135          if (hclose(memfile) != 0) {
   136              abort();
   137          }
   138          return 0;
   139      }
   140      switch (ht_file->format.category) {
   141          case sequence_data:
   142              view_sam(ht_file);
   143              break;
   144          case variant_data:
   145              view_vcf(ht_file);
   146              break;
   147          default:
   148              break;
   149      }
   150      hts_close(ht_file);
   151      return 0;
   152  }
