  3627  int fastq_state_set(samFile *fp, enum hts_fmt_option opt, ...) {
  3628      va_list args;
  3629
  3630      if (!fp)
  3631          return -1;
  3632      if (!fp->state)
  3633          if (!(fp->state = fastq_state_init(fp->format.format == fastq_format
  3634                                             ? '@' : '>')))
  3635              return -1;
  3636
  3637      fastq_state *x = (fastq_state *)fp->state;
  3638
  3639      switch (opt) {
  3640      case FASTQ_OPT_CASAVA:
  3641          x->casava = 1;
  3642          break;
  3643
  3644      case FASTQ_OPT_NAME2:
  3645          x->sra_names = 1;
  3646          break;
  3647
  3648      case FASTQ_OPT_AUX: {
  3649          va_start(args, opt);
  3650          x->aux = 1;
  3651          char *tag = va_arg(args, char *);
  3652          va_end(args);
  3653          if (tag && strcmp(tag, "1") != 0) {
  3654              if (!x->tags)
  3655                  if (!(x->tags = kh_init(tag)))
  3656                      return -1;
  3657
  3658              size_t i, tlen = strlen(tag);
  3659              for (i = 0; i+3 <= tlen+1; i += 3) {
  3660                  if (tag[i+0] == ',' || tag[i+1] == ',' ||
  3661                      !(tag[i+2] == ',' || tag[i+2] == '\0')) {
  3662                      hts_log_warning("Bad tag format '%.3s'; skipping option", tag+i);
  3663                      break;
  3664                  }
  3665                  int ret, tcode = tag[i+0]*256 + tag[i+1];
  3666                  kh_put(tag, x->tags, tcode, &ret);
  3667                  if (ret < 0)
  3668                      return -1;
  3669              }
  3670          }
  3671          break;
  3672      }
  3673
  3674      case FASTQ_OPT_BARCODE: {
  3675          va_start(args, opt);
  3676          char *bc = va_arg(args, char *);
  3677          va_end(args);
  3678          strncpy(x->BC, bc, 2);
  3679          x->BC[2] = 0;
  3680          break;
  3681      }
  3682
  3683      case FASTQ_OPT_RNUM:
  3684          x->rnum = 1;
  3685          break;
  3686
  3687      default:
  3688          break;
  3689      }
  3690      return 0;
  3691  }
