  3693  static int fastq_parse1(htsFile *fp, bam1_t *b) {
  3694      fastq_state *x = (fastq_state *)fp->state;
  3695      size_t i, l;
  3696      int ret = 0;
  3697
  3698      if (fp->format.format == fasta_format && fp->line.s) {
  3699          // For FASTA we've already read the >name line; steal it
  3700          // Not the most efficient, but we don't optimise for fasta reading.
  3701          if (fp->line.l == 0)
  3702              return -1; // EOF
  3703
  3704          free(x->name.s);
  3705          x->name = fp->line;
  3706          fp->line.l = fp->line.m = 0;
  3707          fp->line.s = NULL;
  3708      } else {
  3709          // Read a FASTQ format entry.
  3710          ret = hts_getline(fp, KS_SEP_LINE, &x->name);
  3711          if (ret == -1)
  3712              return -1;  // EOF
  3713          else if (ret < -1)
  3714              return ret; // ERR
  3715      }
  3716
  3717      // Name
  3718
  3719      if (*x->name.s != x->nprefix)
  3720          return -2;
  3721
  3722      // Reverse the SRA strangeness of putting the run_name.number before
  3723      // the read name.
  3724      i = 0;
  3725      char *name = x->name.s+1;
  3726      if (x->sra_names) {
  3727          char *cp = strpbrk(x->name.s, " \t");
  3728          if (cp) {
  3729              while (*cp == ' ' || *cp == '\t')
  3730                  cp++;
  3731              *--cp = '@';
  3732              i = cp - x->name.s;
  3733              name = cp+1;
  3734          }
  3735      }
  3736
  3737      l = x->name.l;
  3738      char *s = x->name.s + i;
  3739      while (i < l && !isspace_c(s[i]))
  3740          i++;
  3741      if (i < l) {
  3742          s[i] = 0;
  3743          x->name.l = i++;
  3744      }
  3745
  3746      // Comment; a kstring struct, but pointer into name line.  (Do not free)
  3747      while (i < l && isspace_c(s[i]))
  3748          i++;
  3749      x->comment.s = s+i;
  3750      x->comment.l = l - i;
  3751
  3752      // Seq
  3753      x->seq.l = 0;
  3754      for (;;) {
  3755          if ((ret = hts_getline(fp, KS_SEP_LINE, &fp->line)) < 0)
  3756              if (fp->format.format == fastq_format || ret < -1)
  3757                  return -2;
  3758          if (*fp->line.s == (fp->format.format == fastq_format ? '+' : '>')
  3759              || ret == -1)
  3760              break;
  3761          if (kputsn(fp->line.s, fp->line.l, &x->seq) < 0)
  3762              return -2;
  3763      }
  3764
  3765      // Qual
  3766      if (fp->format.format == fastq_format) {
  3767          size_t remainder = x->seq.l;
  3768          x->qual.l = 0;
  3769          do {
  3770              if (hts_getline(fp, KS_SEP_LINE, &fp->line) < 0)
  3771                  return -2;
  3772              if (fp->line.l > remainder)
  3773                  return -2;
  3774              if (kputsn(fp->line.s, fp->line.l, &x->qual) < 0)
  3775                  return -2;
